const KEEP = /(automat|\bai\b|\bml\b|llm|agent|n8n|zapier|no-?code|low-?code|gtm|growth|workflow|prompt|intern\b|internship|junior|entry|trainee|apprentice|rpa|integration|chatbot|machine learning)/i;
const DROP = /(senior|\bsr\b|staff|principal|\blead\b|head of|director|\bvp\b|manager|architect|10\+|[5-9]\+? years|sales|writer|copywrit|support|assistant|admin|recruit|designer|accountant)/i;
const clean = (s) => String(s || '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/[\u200B-\u200F\u2060\uFEFF]/g, '')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 1200);
const decode = (s) => s.replace(/&#x2F;/g, '/').replace(/&#x27;/g, "'").replace(/&quot;/g, '"').replace(/&gt;/g, '>').replace(/&lt;/g, '<').replace(/&amp;/g, '&');
const jobs = [];
for (const item of $input.all()) {
  const j = item.json;
  if (Array.isArray(j.jobs)) {
    for (const r of j.jobs) {
      jobs.push({ jobKey: 'remotive-' + r.id, source: 'Remotive', title: r.title, company: r.company_name, location: r.candidate_required_location || '', type: r.job_type || '', pay: r.salary || '', url: r.url, posted: r.publication_date, text: clean(r.description) });
    }
  } else if (Array.isArray(j.hits)) {
    for (const h of j.hits) {
      if (!h.comment_text || String(h.parent_id) !== String(h.story_id)) continue;
      const first = decode(String(h.comment_text).split(/<p>/i)[0].replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
      const parts = first.split('|').map(s => s.trim());
      jobs.push({ jobKey: 'hn-' + h.objectID, source: 'HN Who is hiring', title: (parts.slice(1, 3).join(' | ') || first).slice(0, 120), company: parts[0].slice(0, 60), location: /remote/i.test(first) ? first.slice(0, 120) : '', type: 'HN', pay: '', url: 'https://news.ycombinator.com/item?id=' + h.objectID, posted: h.created_at, text: decode(clean(h.comment_text)), header: first });
    }
  } else if (j.position && j.id) {
    jobs.push({ jobKey: 'remoteok-' + j.id, source: 'RemoteOK', title: j.position, company: j.company, location: j.location || '', type: (j.tags || []).join(', '), pay: j.salary_min ? j.salary_min + '-' + j.salary_max + ' USD/yr' : '', url: j.url, posted: j.date, text: clean(j.description) });
  }
}
const bySource = {};
for (const j of jobs) {
  const head = j.header || j.title;
  if (DROP.test(head)) continue;
  if (!KEEP.test(j.header || (j.title + ' ' + j.type))) continue;
  (bySource[j.source] = bySource[j.source] || []).push(j);
}
const picked = Object.values(bySource).flatMap(list => list.sort((a, b) => new Date(b.posted) - new Date(a.posted)).slice(0, 6));
return picked.map(({ header, ...rest }) => ({ json: rest }));

