const posts = $('Skip Seen Postings').all();
const out = [];
$input.all().forEach((item, i) => {
  const idx = item.pairedItem && item.pairedItem.item !== undefined ? item.pairedItem.item : i;
  const p = (posts[idx] || posts[i] || { json: {} }).json;
  const j = item.json;
  let raw = j.output ?? j.response ?? j.text ?? j.message ?? '';
  if (typeof raw !== 'string') raw = JSON.stringify(raw);
  let parsed = null;
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) { try { parsed = JSON.parse(m[0]); } catch (e) { parsed = null; } }
  out.push({ json: {
    score: parsed ? Number(parsed.score) || 0 : 0,
    verdict: parsed ? parsed.verdict : 'parse_failed',
    reason: parsed ? parsed.reason : (j.error || raw).toString().slice(0, 200),
    opener: parsed ? parsed.opener : '',
    title: p.title, company: p.company, location: p.location, pay: p.pay, url: p.url
  } });
});
return out;

const hits = $input.first().json.hits || [];
const t = hits.find(h => /^Ask HN: Who is hiring/i.test(h.title || ''));
return [{ json: { threadId: t ? t.objectID : 'none', title: t ? t.title : '' } }];
